// Dart2LexerInit initializes any static state used to implement Dart2Lexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewDart2Lexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func Dart2LexerInit() {
	staticData := &Dart2LexerLexerStaticData
	staticData.once.Do(dart2lexerLexerInit)
}

// NewDart2Lexer produces a new lexer instance for the optional input antlr.CharStream.
func NewDart2Lexer(input antlr.CharStream) *Dart2Lexer {
	Dart2LexerInit()
	l := new(Dart2Lexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &Dart2LexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "Dart2Lexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

